def apply_create_query(
    base: Task | None,
    query: Query,
    context: Query,
    *,
    status: str,
    command: str,
) -> Task | None:
    task = Task(
        uuid=str(uuidlib.uuid4()),
        status=status,
        summary=base.summary if base else "",
        notes=base.notes if base else "",
        tags=sorted(base.tags[:]) if base else [],
        project=base.project if base else "",
        priority=base.priority if base else "P2",
        created=now_rfc3339nano(),
        resolved=ZERO_TIME,
        due=base.due if base else ZERO_TIME,
    ) if base else Task(uuid=str(uuidlib.uuid4()), status=status, summary="")

    if base is not None:
        for tag in query.anti_tags:
            task.tags = [item for item in task.tags if item != tag]
        for project_name in query.anti_projects:
            if task.project == project_name:
                task.project = ""
        if query.project == "":
            task.project = ""

    for tag in query.tags:
        if tag not in task.tags:
            task.tags.append(tag)
    if query.project:
        task.project = query.project
    if query.priority:
        task.priority = query.priority
    if query.due != ZERO_TIME:
        task.due = query.due

    merged = context
    if not query.ignore_context and not merged.empty():
        if merged.project and task.project and merged.project != task.project:
            print_red("Could not apply q2, project conflict")
            return None
        for tag in merged.tags:
            if tag not in task.tags:
                task.tags.append(tag)
        if merged.project:
            task.project = merged.project

    task.tags = sorted(set(task.tags))

    if base and query.text:
        task.summary = query.text
    elif query.text:
        task.summary = query.text

    if command == "log":
        task.notes = task.notes if base else ""
    elif base and query.note is not None:
        task.notes = append_note(task.notes, query.note)
    elif base and task.notes and command == "add":
        if not task.notes.endswith("\n"):
            task.notes += "\n"
    elif query.note is not None:
        task.notes = query.note

    if status == "resolved":
        task.resolved = now_rfc3339nano()
    return task


def open_urls(urls: list[str]) -> bool:
    if not urls:
        return False
    commands: list[list[str]]
    if sys.platform.startswith("linux"):
        commands = [["xdg-open"]]
    elif sys.platform == "darwin":
        commands = [["open"]]
    elif sys.platform.startswith("win"):
        commands = [["rundll32", "url.dll,FileProtocolHandler"]]
    else:
        commands = []
    if not commands:
        return False
    for url in urls:
        ok = False
        for cmd in commands:
            proc = subprocess.run(
                cmd + [url],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
            )
            if proc.returncode == 0:
                ok = True
                break
        if not ok:
            return False
    return True


def extract_urls(text: str) -> list[str]:
    results: list[str] = []
    for match in re.finditer(r"https?://\S+", text):
        url = match.group(0).rstrip(').,]}>";\'')
        if url not in results:
            results.append(url)
    return results


def edit_with_editor(initial: str, suffix: str) -> str | None:
    editor = os.environ.get("EDITOR")
    if not editor:
        return None
    with tempfile.NamedTemporaryFile("w+", suffix=suffix, delete=False, encoding="utf-8") as handle:
        path = Path(handle.name)
        handle.write(initial)
        handle.flush()
    try:
        proc = subprocess.run(shlex.split(editor) + [str(path)], check=False)
        if proc.returncode != 0:
            return None
        return path.read_text(encoding="utf-8")
    finally:
        try:
            path.unlink()
        except OSError:
            pass


