def command_show_projects(repo: Repo) -> int:
    tasks = repo.load_tasks()
    grouped: dict[str, list[Task]] = {}
    for task in tasks:
        if task.status == "template" or not task.project:
            continue
        grouped.setdefault(task.project, []).append(task)
    projects: list[dict[str, object]] = []
    for name in sorted(grouped):
        items = grouped[name]
        open_items = [task for task in items if task.status in {"pending", "active", "paused"}]
        resolved_items = [task for task in items if task.status == "resolved"]
        created = min(items, key=lambda t: parse_rfc3339nano(t.created)).created
        if resolved_items:
            resolved_value = max(resolved_items, key=lambda t: parse_rfc3339nano(t.resolved)).resolved
        else:
            resolved_value = ZERO_TIME
        priority = "P3"
        if open_items:
            priority = min(open_items, key=lambda t: priority_rank(t.priority)).priority
        projects.append(
            {
                "name": name,
                "taskCount": len(items),
                "resolvedCount": len(resolved_items),
                "active": any(task.status == "active" for task in open_items),
                "created": created,
                "resolved": resolved_value,
                "priority": priority,
            }
        )
    dump_json(projects)
    return 0


