def transition_task(task: Task, new_status: str) -> bool:
    valid = {
        ("pending", "active"),
        ("paused", "active"),
        ("active", "paused"),
        ("pending", "resolved"),
        ("active", "resolved"),
        ("paused", "resolved"),
        ("pending", "template"),
    }
    if (task.status, new_status) not in valid:
        print_red(f"invalid state transition: {task.status} -> {new_status}")
        return False
    task.status = new_status
    return True


def resolve_id_targets(repo: Repo, ids: list[int]) -> tuple[list[Task], int]:
    tasks = repo.load_tasks()
    selected: list[Task] = []
    for id_value in ids:
        task = find_task_by_id(tasks, id_value)
        if task is None:
            print_red(f"no open task with ID {id_value} exists")
            return [], 1
        selected.append(task)
    return selected, 0


def command_start(repo: Repo, before: list[str], after: list[str]) -> int:
    ids = [int(token) for token in before if is_pure_int(token)]
    if not ids and after and all(is_pure_int(token) for token in after):
        ids = [int(token) for token in after]
    if not ids:
        return command_create(repo, "start", after)
    tasks, code = resolve_id_targets(repo, ids)
    if code:
        return code
    for task in tasks:
        if not transition_task(task, "active"):
            return 1
        write_task(repo, task)
        message = f"Started {task.id}: {task.summary}"
        sys.stdout.write("\n" + message + "\n" if False else f"\n{message}\n")
        if not commit_changes(repo, message):
            return 1
    return 0


def command_stop(repo: Repo, before: list[str], after: list[str]) -> int:
    ids = [int(token) for token in before if is_pure_int(token)]
    trailing = after[:]
    if not ids:
        while trailing and is_pure_int(trailing[0]):
            ids.append(int(trailing.pop(0)))
    text = " ".join(trailing)
    tasks, code = resolve_id_targets(repo, ids)
    if code:
        return code
    for task in tasks:
        if not transition_task(task, "paused"):
            return 1
        task.notes = append_action_note(task.notes, text)
        write_task(repo, task)
        message = f"Stopped {task.id}: {task.summary}"
        sys.stdout.write(f"{message}\n")
        if not commit_changes(repo, message):
            return 1
    return 0


