def parse_context_tokens(tokens: list[str]) -> Query:
    query = Query()
    for token in tokens:
        if token == "--":
            query.ignore_context = True
        elif token.startswith("+") and len(token) > 1:
            query.tags.append(token[1:])
        elif token.startswith("-project:") and len(token) > len("-project:"):
            query.anti_projects.append(token[len("-project:") :])
        elif token.startswith("-") and len(token) > 1:
            query.anti_tags.append(token[1:])
        elif token.startswith("project:") and len(token) > len("project:"):
            query.project = token[len("project:") :]
    return query


def parse_query_tokens(tokens: list[str]) -> Query:
    query = Query()
    text_bits: list[str] = []
    for token in tokens:
        if token == "--":
            query.ignore_context = True
        elif token.startswith("+") and len(token) > 1:
            query.tags.append(token[1:])
        elif token.startswith("-project:") and len(token) > len("-project:"):
            query.anti_projects.append(token[len("-project:") :])
        elif token.startswith("-") and len(token) > 1:
            query.anti_tags.append(token[1:])
        elif token.startswith("project:"):
            query.project = token[len("project:") :]
        elif token in PRIORITIES:
            query.priority = token
        elif token.startswith("due:"):
            query.due = parse_due_token(token[len("due:") :])
        elif token.startswith("template:") and token[len("template:") :].isdigit():
            query.template_id = int(token[len("template:") :])
        else:
            text_bits.append(token)
    query.text = " ".join(text_bits)
    return query


